import csv

DATA = "/app/dataset"
DISPOSAL_TS = "2023-07-18 03:17:00"  # bulk dispatch of Meat/Frozen goods during the cold-chain failure


def answer() -> int:
    catalog = {}
    ean_to_id = {}
    with open(f"{DATA}/product_catalog.csv", newline="") as f:
        for r in csv.DictReader(f):
            catalog[r["product_id"]] = float(r["unit_price"].replace(",", "."))
            ean_to_id[r["ean_code"]] = r["product_id"]

    seen = set()
    total = 0.0
    with open(f"{DATA}/warehouse_dispatches.csv", newline="") as f:
        for r in csv.DictReader(f):
            key = (r["timestamp"], r["product_id"], r["quantity"], r["total_weight_kg"])
            if key in seen:  # double-logged dispatch rows (Jul 10-14)
                continue
            seen.add(key)
            if r["timestamp"] == DISPOSAL_TS:
                continue
            pid = ean_to_id.get(r["product_id"], r["product_id"])
            total += int(r["quantity"]) * catalog[pid]
    return int(round(total))


if __name__ == "__main__":
    import json
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)
EOF
python /app/answer.py && cat /app/answer.json
